package com.zomiggy.service;
import com.zomiggy.dto.ApiDtos.*; import com.zomiggy.entity.*; import com.zomiggy.repository.*; import com.zomiggy.security.JwtService; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.security.SecureRandom;
@Service public class AuthService { private final UserRepository users; private final OtpCodeRepository otps; private final JwtService jwt; private final boolean expose; public AuthService(UserRepository u,OtpCodeRepository o,JwtService j,@Value("${app.otp.expose}") boolean expose){users=u;otps=o;jwt=j;this.expose=expose;} public String request(OtpRequest r){String code=String.format("%06d",new SecureRandom().nextInt(1000000));otps.save(new OtpCode(r.mobile(),code)); return expose?code:null;} @Transactional public AuthResponse verify(VerifyOtpRequest r){var otp=otps.findTopByMobileOrderByIdDesc(r.mobile()).orElseThrow(()->new IllegalArgumentException("Invalid OTP"));if(otp.isExpired())throw new IllegalArgumentException("OTP expired. Please request a new OTP.");if(!otp.valid(r.otp()))throw new IllegalArgumentException("Invalid OTP");otp.markUsed();var user=users.findByMobile(r.mobile()).orElseGet(()->users.save(new User(r.mobile())));return new AuthResponse(jwt.generate(user),new UserResponse(user.getId(),user.getName(),user.getMobile(),user.getAddress(),user.getCoins()));} public User current(String mobile){return users.findByMobile(mobile).orElseThrow();} }